bool ggml_cuda_supports_ssm_conv(const ggml_tensor * dst) {
    if (!dst || dst->op != GGML_OP_SSM_CONV || dst->type != GGML_TYPE_F32) return false;
    const ggml_tensor * const x = dst->src[0], * const w = dst->src[1];
    if (!x || !w || (x->type != GGML_TYPE_BF16 && x->type != GGML_TYPE_F32) || w->type != GGML_TYPE_F32) return false;
    const int64_t W = x->ne[0], C = x->ne[1], B = x->ne[2], K = w->ne[0];
    if (W <= 0 || C <= 0 || C % 128 || B <= 0 || x->ne[3] != 1 ||
        (K != 3 && K != 4 && K != 5 && K != 9 && K != 15) || W < K ||
        w->ne[1] != C || w->ne[2] != 1 || w->ne[3] != 1 ||
        dst->ne[0] != C || dst->ne[1] != W - K + 1 || dst->ne[2] != B || dst->ne[3] != 1) return false;
